  const field=(id,label,type="number",placeholder="",extra={})=>`<label class="field"><span>${label}</span>${type==="select"?`<select id="${id}">${extra.options.map(o=>`<option>${esc(o)}</option>`).join("")}</select>`:type==="textarea"?`<textarea id="${id}" rows="3" placeholder="${esc(placeholder)}"></textarea>`:`<input id="${id}" type="${type}" ${type==="number"?'min="0" step="any"':""} placeholder="${esc(placeholder)}" ${extra.value!==undefined?`value="${esc(extra.value)}"`:""} ${extra.required?'required':""}>`}</label>`;
